```

The `.sln` must be a valid VS-format solution containing that one project so that
`dotnet build -c Release` at the repo root works. Do **not** add a `global.json`.

## 2. Public API — implement these signatures verbatim

Other cards compile against them; do not rename anything.

```csharp
namespace BatchRenameStudio.Core;

public enum ApplyToMode { Name, NameAndExtension }
public enum SortMode { Name, Created, Modified }

public static class NameParts
{
    // Rule 2. dot = LAST index of '.'; if dot > 0 -> (name[0..dot), name[dot+1..]) else (name, "")
    public static (string Base, string Ext) Split(string fileName);
    // Rule 6. ext non-empty -> base + "." + ext ; else base
    public static string Join(string baseName, string ext);
}

public sealed class ParamBag
{
    public string GetString(string key, string fallback = "");
    public int GetInt(string key, int fallback = 0);
    public bool GetBool(string key, bool fallback = false);
    public void Set(string key, string value);
    public void Set(string key, int value);
    public void Set(string key, bool value);
    public bool Has(string key);
    public void Remove(string key);
    public IReadOnlyDictionary<string, object?> Raw { get; }   // ordered by insertion
    public ParamBag Clone();
}

public sealed class RuleStep
{
    public RuleStep(string op);
    public string Op { get; set; }
    public ParamBag Params { get; }
    public RuleStep Clone();
    public string Describe();   // short one-line human summary for the GUI list, e.g. "replace \"a\" -> \"b\""
}

public sealed class RuleSet
{
    public ApplyToMode ApplyTo { get; set; }        // default Name
    public SortMode Sort { get; set; }              // default Name
    public List<RuleStep> Steps { get; }
    public static RuleSet FromJson(string json);    // throws RuleParseException
    public static RuleSet LoadFile(string path);    // throws RuleParseException / IO exceptions
    public string ToJson();                         // stable, indented, round-trips FromJson
}

public sealed class RuleParseException : Exception
{
    public RuleParseException(string message);
    public RuleParseException(string message, Exception inner);
}

public sealed class EvalState
{
    public EvalState(string originalName, ApplyToMode applyTo, int index);
    public string OriginalName { get; }
    public string OriginalBase { get; }   // rule 2 split of OriginalName
    public string OriginalExt { get; }    // rule 2 split of OriginalName (no dot)
    public ApplyToMode ApplyTo { get; }
    public int Index { get; }             // 0-based position in processing order
    public string Target { get; set; }    // the string the steps operate on (rule 3)
    public string Ext { get; set; }       // live extension; only used when ApplyTo == Name
    public string BuildProposed();        // rule 6
}

public interface IRenameOp
{
    string Op { get; }
    void Apply(EvalState state);
}

public static class OpFactory
{
    public static IRenameOp Create(RuleStep step);            // unknown op -> a no-op instance
    public static IReadOnlyList<string> KnownOps { get; }     // the 14 ids, in catalog order
}

public sealed class FileEntry
{
    public FileEntry(string fullPath, string name, DateTime createdUtc, DateTime modifiedUtc);
    public string FullPath { get; }
    public string Name { get; }
    public DateTime CreatedUtc { get; }
    public DateTime ModifiedUtc { get; }
}

public static class FileScanner
{
    public static List<FileEntry> Scan(string directory);                       // rule 1: files only, non-recursive
    public static List<FileEntry> ScanSorted(string directory, SortMode sort);  // rule 5
    public static void SortInPlace(List<FileEntry> files, SortMode sort);
}

public static class NameValidator
{
    // rule 7 "invalid" test. reason is a short english explanation, "" when valid.
    public static bool IsInvalid(string proposedName, out string reason);
}

public sealed class StepTrace
{
    public int Index { get; init; }
    public string Op { get; init; }
    public string Before { get; init; }
    public string After { get; init; }
}

public sealed class EvaluatedFile
{
    public FileEntry File { get; init; }
    public string Original { get; init; }
    public string Proposed { get; init; }
    public string Status { get; set; }        // "ok" | "collision" | "unchanged" | "invalid"
    public string Reason { get; set; }
    public List<StepTrace> Steps { get; init; }
}

public static class RenameEngine
{
    public static List<EvaluatedFile> Evaluate(IReadOnlyList<FileEntry> filesInProcessingOrder, RuleSet rules);
    public static List<EvaluatedFile> EvaluateDirectory(string directory, RuleSet rules);  // scan + sort + evaluate
    public static PlanDocument BuildPlan(IReadOnlyList<EvaluatedFile> evaluated);
    public static TraceDocument BuildTrace(IReadOnlyList<EvaluatedFile> evaluated);
}
```

`PlanModels.cs` — the JSON property names are part of a fixed external contract.
Put an explicit `[JsonPropertyName("...")]` on **every** property.

```csharp
public sealed class PlanDocument   { schemaVersion:int=1, items:List<PlanItem>, summary:PlanSummary }
public sealed class PlanItem       { original:string, proposed:string, status:string, reason:string }
public sealed class PlanSummary    { total:int, ok:int, collision:int, unchanged:int, invalid:int }
public sealed class TraceDocument  { schemaVersion:int=1, files:List<TraceFile> }
public sealed class TraceFile      { original:string, steps:List<TraceStep>, proposed:string, status:string }
public sealed class TraceStep      { index:int, op:string, before:string, after:string }
```

Property order inside each object must match the order listed above.

```csharp
public static class JsonIo
{
    public static JsonSerializerOptions DocumentOptions { get; }  // WriteIndented = true,
                                                                  // Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    // UTF-8, NO BOM: File.WriteAllBytes(path, JsonSerializer.SerializeToUtf8Bytes(doc, DocumentOptions))
    public static void WriteDocument<T>(string path, T document);
}
```

`OpCatalog.cs` describes the ops for the GUI. Provide:

```csharp
public enum ParamKind { Text, Integer, Boolean, Choice }
public sealed class ParamSpec
{
    public string Key; public string Label; public ParamKind Kind;
    public object? Default; public string[] Choices;   // non-empty only for Choice
    public string Help;                                // one short sentence
}
public sealed class OpSpec
{
    public string Op; public string DisplayName; public string Summary;
    public IReadOnlyList<ParamSpec> Params;
}
public static class OpCatalog
{
    public static IReadOnlyList<OpSpec> All { get; }        // all 14, in the order of §5
    public static OpSpec? Find(string op);
    public static RuleStep CreateDefaultStep(string op);    // params pre-filled with the defaults below
}
```

## 3. Entry-point stubs (WC-02 / WC-03 will replace the bodies)

`Program.cs` — final version, later cards must NOT modify this file:

```csharp
using BatchRenameStudio.Cli;
using BatchRenameStudio.Forms;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
