        $label = if ($mode -eq '--plan') { 'plan' } else { 'trace' }
        $out = Join-Path $caseDir.FullName "actual-$label.json"
        $r = Invoke-Contract $case $mode $dir $rules $out

        if ($r.Exit -ne 0) { Fail $case "$mode exit code $($r.Exit); stderr: $((Get-Content $r.StdErr -Raw))"; continue }
        if (-not (Test-Path $out)) { Fail $case "$mode did not write $out"; continue }

        $bytes = [System.IO.File]::ReadAllBytes($out)
        if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { Fail $case "$mode output has a UTF-8 BOM" }

        $soText = if (Test-Path $r.StdOut) { [System.IO.File]::ReadAllText($r.StdOut) } else { '' }
        $lines = @($soText -split "`r?`n" | Where-Object { $_ -ne '' })
        if ($lines.Count -ne 1) { Fail $case "$mode printed $($lines.Count) stdout line(s), expected exactly 1. Content: '$soText'" }

        $after = Get-ChildItem $dir -File | ForEach-Object { $_.Name } | Sort-Object
        if (($before -join '|') -cne ($after -join '|')) { Fail $case "$mode MODIFIED THE FOLDER: '$($before -join '|')' -> '$($after -join '|')'" }

        $expectFile = Join-Path $caseDir.FullName "expect-$label.json"
        if (Test-Path $expectFile) {
            $exp = [System.IO.File]::ReadAllText($expectFile) | ConvertFrom-Json
            $act = [System.IO.File]::ReadAllText($out) | ConvertFrom-Json
            Compare-Node $exp $act $label $case
        }
    }
}

