using System.Globalization;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

public sealed class TemplateOp : IRenameOp
{
    private static readonly Regex TokenScanner = new(@"\{[^{}]*\}", RegexOptions.None, TimeSpan.FromSeconds(1));
    private static readonly Regex CounterToken = new("^n:(0+)$", RegexOptions.None, TimeSpan.FromSeconds(1));

    private readonly string _format;

    public TemplateOp(RuleStep step)
    {
        _format = step.Params.GetString("format", "{name}-{ext}-{n:000}");
    }

    public string Op => "template";

    public void Apply(EvalState state)
    {
        var nameSnapshot = state.Target;
        var lenSnapshot = nameSnapshot.Length.ToString(CultureInfo.InvariantCulture);
        var extSnapshot = state.OriginalExt;
        var counter = (long)state.Index + 1;

        state.Target = TokenScanner.Replace(_format, m =>
        {
            var inner = m.Value[1..^1];

            switch (inner)
            {
                case "name":
                    return nameSnapshot;
                case "ext":
                    return extSnapshot;
                case "len":
                    return lenSnapshot;
            }

            var counterMatch = CounterToken.Match(inner);
            if (counterMatch.Success)
            {
                var padWidth = counterMatch.Groups[1].Length;
                return counter.ToString(new string('0', padWidth), CultureInfo.InvariantCulture);
            }

            return m.Value;
        });
    }
}

