namespace BatchRenameStudio.Core.Ops;

public sealed class SlugOp : IRenameOp
{
    private static readonly Regex NonAlphaNumeric = new("[^a-z0-9]+", RegexOptions.None, TimeSpan.FromSeconds(1));

    private readonly string _separator;

    public SlugOp(RuleStep step)
    {
        _separator = step.Params.GetString("separator", "-");
    }

    public string Op => "slug";

    public void Apply(EvalState state)
    {
        var lowered = state.Target.ToLowerInvariant();
        var result = NonAlphaNumeric.Replace(lowered, _separator);

        if (_separator.Length > 0)
        {
            while (result.StartsWith(_separator, StringComparison.Ordinal))
            {
                result = result[_separator.Length..];
            }

            while (result.EndsWith(_separator, StringComparison.Ordinal))
            {
                result = result[..^_separator.Length];
            }
        }

        state.Target = result;
    }
}

