namespace BatchRenameStudio.Core;

public sealed class StepTrace
{
    public int Index { get; init; }
    public string Op { get; init; } = "";
    public string Before { get; init; } = "";
    public string After { get; init; } = "";
}

public sealed class EvaluatedFile
{
    public FileEntry File { get; init; } = null!;
    public string Original { get; init; } = "";
    public string Proposed { get; init; } = "";
    public string Status { get; set; } = "";        // "ok" | "collision" | "unchanged" | "invalid"
    public string Reason { get; set; } = "";
    public List<StepTrace> Steps { get; init; } = new();
}

public static class RenameEngine
{
    public static List<EvaluatedFile> Evaluate(IReadOnlyList<FileEntry> filesInProcessingOrder, RuleSet rules)
    {
        var ops = rules.Steps.Select(OpFactory.Create).ToList();
        var n = filesInProcessingOrder.Count;
        var proposed = new string[n];
        var stepsList = new List<StepTrace>[n];

        for (var i = 0; i < n; i++)
        {
            var file = filesInProcessingOrder[i];
            var state = new EvalState(file.Name, rules.ApplyTo, i);
            var traces = new List<StepTrace>(ops.Count);

            for (var k = 0; k < ops.Count; k++)
            {
                var before = state.Target;
                ops[k].Apply(state);
                traces.Add(new StepTrace { Index = k, Op = rules.Steps[k].Op, Before = before, After = state.Target });
            }

            proposed[i] = state.BuildProposed();
            stepsList[i] = traces;
        }

        var originalDict = BuildIndexLookup(n, i => filesInProcessingOrder[i].Name);
        var proposedDict = BuildIndexLookup(n, i => proposed[i]);

        var result = new List<EvaluatedFile>(n);
        for (var i = 0; i < n; i++)
        {
            var original = filesInProcessingOrder[i].Name;
            string status;
            string reason;

            if (NameValidator.IsInvalid(proposed[i], out var invalidReason))
            {
                status = "invalid";
                reason = invalidReason;
            }
            else if (IsCollision(i, proposed[i], originalDict, proposedDict, out var collisionReason))
            {
                status = "collision";
                reason = collisionReason;
            }
            else if (string.Equals(proposed[i], original, StringComparison.Ordinal))
            {
                status = "unchanged";
                reason = "";
            }
            else
            {
                status = "ok";
                reason = "";
            }

            result.Add(new EvaluatedFile
            {
                File = filesInProcessingOrder[i],
                Original = original,
                Proposed = proposed[i],
                Status = status,
                Reason = reason,
                Steps = stepsList[i]
            });
        }

        return result;
    }

    public static List<EvaluatedFile> EvaluateDirectory(string directory, RuleSet rules)
    {
        var files = FileScanner.ScanSorted(directory, rules.Sort);
        return Evaluate(files, rules);
    }

    public static PlanDocument BuildPlan(IReadOnlyList<EvaluatedFile> evaluated)
    {
        var doc = new PlanDocument();
        int ok = 0, collision = 0, unchanged = 0, invalid = 0;

        foreach (var e in evaluated)
        {
            doc.Items.Add(new PlanItem { Original = e.Original, Proposed = e.Proposed, Status = e.Status, Reason = e.Reason });

            switch (e.Status)
            {
                case "ok":
                    ok++;
                    break;
                case "collision":
                    collision++;
                    break;
                case "unchanged":
                    unchanged++;
                    break;
                case "invalid":
                    invalid++;
                    break;
            }
        }

        doc.Summary = new PlanSummary
        {
            Total = evaluated.Count,
            Ok = ok,
            Collision = collision,
            Unchanged = unchanged,
            Invalid = invalid
        };

        return doc;
    }

    public static TraceDocument BuildTrace(IReadOnlyList<EvaluatedFile> evaluated)
    {
        var doc = new TraceDocument();

        foreach (var e in evaluated)
        {
            var traceFile = new TraceFile { Original = e.Original, Proposed = e.Proposed, Status = e.Status };
            foreach (var step in e.Steps)
            {
                traceFile.Steps.Add(new TraceStep { Index = step.Index, Op = step.Op, Before = step.Before, After = step.After });
            }

            doc.Files.Add(traceFile);
        }

        return doc;
    }

    private static Dictionary<string, List<int>> BuildIndexLookup(int n, Func<int, string> nameOf)
    {
        var dict = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (var i = 0; i < n; i++)
        {
            var name = nameOf(i);
            if (!dict.TryGetValue(name, out var list))
            {
                list = new List<int>();
                dict[name] = list;
            }

            list.Add(i);
        }

        return dict;
    }

    private static bool IsCollision(
        int index,
        string proposed,
        Dictionary<string, List<int>> originalDict,
        Dictionary<string, List<int>> proposedDict,
        out string reason)
    {
        if (originalDict.TryGetValue(proposed, out var originalIndices))
        {
            foreach (var idx in originalIndices)
            {
                if (idx != index)
                {
                    reason = "collides with existing file";
                    return true;
                }
            }
        }

        if (proposedDict.TryGetValue(proposed, out var proposedIndices))
        {
            foreach (var idx in proposedIndices)
            {
                if (idx != index)
                {
                    reason = "collides with another item's proposed name";
                    return true;
                }
            }
        }

        reason = "";
        return false;
    }
}

