            foreach (var step in e.Steps)
            {
                traceFile.Steps.Add(new TraceStep { Index = step.Index, Op = step.Op, Before = step.Before, After = step.After });
            }

            doc.Files.Add(traceFile);
        }

        return doc;
    }

    private static Dictionary<string, List<int>> BuildIndexLookup(int n, Func<int, string> nameOf)
    {
        var dict = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (var i = 0; i < n; i++)
        {
            var name = nameOf(i);
            if (!dict.TryGetValue(name, out var list))
            {
                list = new List<int>();
                dict[name] = list;
            }

            list.Add(i);
        }

        return dict;
    }

    private static bool IsCollision(
        int index,
        string proposed,
        Dictionary<string, List<int>> originalDict,
        Dictionary<string, List<int>> proposedDict,
        out string reason)
    {
        if (originalDict.TryGetValue(proposed, out var originalIndices))
        {
            foreach (var idx in originalIndices)
            {
                if (idx != index)
                {
                    reason = "collides with existing file";
                    return true;
                }
            }
        }

        if (proposedDict.TryGetValue(proposed, out var proposedIndices))
        {
            foreach (var idx in proposedIndices)
            {
                if (idx != index)
                {
                    reason = "collides with another item's proposed name";
                    return true;
                }
            }
        }

        reason = "";
        return false;
    }
}

