namespace BatchRenameStudio.Core;

public static class NameValidator
{
    private static readonly char[] IllegalChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedNames = new(StringComparer.OrdinalIgnoreCase)
    {
        "CON", "PRN", "AUX", "NUL",
        "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
        "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9"
    };

    // rule 7 "invalid" test.
    public static bool IsInvalid(string proposedName, out string reason)
    {
        if (proposedName.Length == 0)
        {
            reason = "name is empty";
            return true;
        }

        if (proposedName.Length > 255)
        {
            reason = "name is longer than 255 characters";
            return true;
        }

        foreach (var c in proposedName)
        {
            if (c < 0x0020)
            {
                reason = "contains a control character";
                return true;
            }

            foreach (var illegal in IllegalChars)
            {
                if (c == illegal)
                {
                    reason = $"contains illegal character '{illegal}'";
                    return true;
                }
            }
        }

        var (baseName, _) = NameParts.Split(proposedName);
        if (ReservedNames.Contains(baseName))
        {
            reason = $"\"{baseName}\" is a reserved device name";
            return true;
        }

        reason = "";
        return false;
    }
}

