namespace BatchRenameStudio.Core;

public static class FileScanner
{
    // Rule 1: files only, non-recursive.
    public static List<FileEntry> Scan(string directory)
    {
        var result = new List<FileEntry>();

        foreach (var path in Directory.EnumerateFileSystemEntries(directory))
        {
            var attributes = File.GetAttributes(path);
            if ((attributes & FileAttributes.Directory) != 0)
            {
                continue;
            }

            var info = new FileInfo(path);
            result.Add(new FileEntry(info.FullName, info.Name, info.CreationTimeUtc, info.LastWriteTimeUtc));
        }

        return result;
    }

    // Rule 5.
    public static List<FileEntry> ScanSorted(string directory, SortMode sort)
    {
        var files = Scan(directory);
        SortInPlace(files, sort);
        return files;
    }

    public static void SortInPlace(List<FileEntry> files, SortMode sort)
    {
        switch (sort)
        {
            case SortMode.Created:
                files.Sort((a, b) =>
                {
                    var cmp = a.CreatedUtc.CompareTo(b.CreatedUtc);
                    return cmp != 0 ? cmp : StringComparer.Ordinal.Compare(a.Name, b.Name);
                });
                break;
            case SortMode.Modified:
                files.Sort((a, b) =>
                {
                    var cmp = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                    return cmp != 0 ? cmp : StringComparer.Ordinal.Compare(a.Name, b.Name);
                });
                break;
            default:
                files.Sort((a, b) => StringComparer.Ordinal.Compare(a.Name, b.Name));
                break;
        }
    }
}

