using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

public sealed class ReplaceOp : IRenameOp
{
    private static readonly TimeSpan MatchTimeout = TimeSpan.FromSeconds(1);

    private readonly string _find;
    private readonly string _replaceWith;
    private readonly bool _regex;
    private readonly bool _ignoreCase;

    public ReplaceOp(RuleStep step)
    {
        _find = step.Params.GetString("find", "");
        _replaceWith = step.Params.GetString("replaceWith", "");
        _regex = step.Params.GetBool("regex", false);
        _ignoreCase = step.Params.GetBool("ignoreCase", false);
    }

    public string Op => "replace";

    public void Apply(EvalState state)
    {
        if (_find.Length == 0)
        {
            return;
        }

        if (_regex)
        {
            try
            {
                var options = _ignoreCase ? RegexOptions.IgnoreCase : RegexOptions.None;
                var regex = new Regex(_find, options, MatchTimeout);
                state.Target = regex.Replace(state.Target, _replaceWith);
            }
            catch (ArgumentException)
            {
                // invalid pattern -> no-op
            }
            catch (RegexMatchTimeoutException)
            {
                // timeout -> no-op
            }

            return;
        }

        var comparison = _ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        state.Target = state.Target.Replace(_find, _replaceWith, comparison);
    }
}

