using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

public sealed class ExtractOp : IRenameOp
{
    private static readonly TimeSpan MatchTimeout = TimeSpan.FromSeconds(1);

    private readonly string _pattern;
    private readonly int _group;

    public ExtractOp(RuleStep step)
    {
        _pattern = step.Params.GetString("pattern", "\\d+");
        _group = step.Params.GetInt("group", 0);
    }

    public string Op => "extract";

    public void Apply(EvalState state)
    {
        Regex regex;
        try
        {
            regex = new Regex(_pattern, RegexOptions.None, MatchTimeout);
        }
        catch (ArgumentException)
        {
            // invalid pattern -> no-op
            return;
        }

        Match match;
        try
        {
            match = regex.Match(state.Target);
        }
        catch (RegexMatchTimeoutException)
        {
            // timeout -> no-op
            return;
        }

        if (!match.Success)
        {
            state.Target = "";
            return;
        }

        if (_group < 0 || _group >= match.Groups.Count)
        {
            state.Target = "";
            return;
        }

        var group = match.Groups[_group];
        state.Target = group.Success ? group.Value : "";
    }
}

