using System.Globalization;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core.Ops;

public sealed class SequenceOp : IRenameOp
{
    private static readonly Regex TokenPattern = new(@"\{n:(0+)\}", RegexOptions.None, TimeSpan.FromSeconds(1));

    private readonly string _pattern;
    private readonly long _start;
    private readonly long _step;
    private readonly string _position;

    public SequenceOp(RuleStep step)
    {
        _pattern = step.Params.GetString("pattern", "{n:000}_");
        _start = step.Params.GetInt("start", 1);
        _step = step.Params.GetInt("step", 1);
        _position = step.Params.GetString("position", "prefix");
    }

    public string Op => "sequence";

    public void Apply(EvalState state)
    {
        var counter = _start + (long)state.Index * _step;

        var match = TokenPattern.Match(_pattern);
        string rendered;
        if (match.Success)
        {
            var padWidth = match.Groups[1].Length;
            var counterText = counter.ToString(new string('0', padWidth), CultureInfo.InvariantCulture);
            rendered = _pattern[..match.Index] + counterText + _pattern[(match.Index + match.Length)..];
        }
        else
        {
            rendered = _pattern;
        }

        state.Target = _position == "suffix" ? state.Target + rendered : rendered + state.Target;
    }
}

