    {
        var sb = new StringBuilder(input.Length);
        var atRunStart = true;

        foreach (var c in input)
        {
            if (char.IsLetter(c))
            {
                sb.Append(atRunStart ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c));
                atRunStart = false;
            }
            else
            {
                sb.Append(c);
                atRunStart = true;
            }
        }

        return sb.ToString();
    }
}

