namespace BatchRenameStudio.Core.Ops;

public sealed class NumberFormatOp : IRenameOp
{
    private readonly int _width;

    public NumberFormatOp(RuleStep step)
    {
        _width = Math.Clamp(step.Params.GetInt("width", 4), 0, 4096);
    }

    public string Op => "numberFormat";

    public void Apply(EvalState state)
    {
        var target = state.Target;
        var start = -1;
        var end = -1;

        for (var i = 0; i < target.Length; i++)
        {
            if (target[i] is >= '0' and <= '9')
            {
                if (start < 0)
                {
                    start = i;
                }

                end = i + 1;
            }
            else if (start >= 0)
            {
                break;
            }
        }

        if (start < 0)
        {
            return;
        }

        var run = target[start..end];
        if (run.Length >= _width)
        {
            return;
        }

        var padded = run.PadLeft(_width, '0');
        state.Target = target[..start] + padded + target[end..];
    }
}

