namespace BatchRenameStudio.Core.Ops;

public sealed class InsertOp : IRenameOp
{
    private readonly string _text;
    private readonly string _position;
    private readonly int _index;

    public InsertOp(RuleStep step)
    {
        _text = step.Params.GetString("text", "");
        _position = step.Params.GetString("position", "prefix");
        _index = step.Params.GetInt("index", 0);
    }

    public string Op => "insert";

    public void Apply(EvalState state)
    {
        switch (_position)
        {
            case "suffix":
                state.Target += _text;
                break;
            case "index":
                var clamped = Math.Clamp(_index, 0, state.Target.Length);
                state.Target = state.Target[..clamped] + _text + state.Target[clamped..];
                break;
            default:
                state.Target = _text + state.Target;
                break;
        }
    }
}

