public sealed class DedupeCharsOp : IRenameOp
{
    public DedupeCharsOp(RuleStep step)
    {
    }

    public string Op => "dedupeChars";

    public void Apply(EvalState state)
    {
        var target = state.Target;
        if (target.Length == 0)
        {
            return;
        }

        var sb = new StringBuilder(target.Length);
        sb.Append(target[0]);
        for (var i = 1; i < target.Length; i++)
        {
            if (target[i] != target[i - 1])
            {
                sb.Append(target[i]);
            }
        }

        state.Target = sb.ToString();
    }
