namespace BatchRenameStudio.Core.Ops;

public sealed class RemoveOp : IRenameOp
{
    private readonly int _from;
    private readonly int _count;

    public RemoveOp(RuleStep step)
    {
        _from = step.Params.GetInt("from", 0);
        _count = step.Params.GetInt("count", 0);
    }

    public string Op => "remove";

    public void Apply(EvalState state)
    {
        var length = state.Target.Length;
        var from = Math.Clamp(_from, 0, length);
        var maxCount = length - from;
        var count = Math.Clamp(_count, 0, maxCount);

        if (count <= 0)
        {
            return;
        }

        state.Target = state.Target.Remove(from, count);
    }
}

