# Acceptance runner: drives the two headless contracts against the hand-computed oracle.
$ErrorActionPreference = 'Stop'
$root = Join-Path $PSScriptRoot 'accept'
$exe  = 'D:\BenchRuns\XL-B-03\src\BatchRenameStudio\bin\Release\net8.0-windows\BatchRenameStudio.exe'
if (-not (Test-Path $exe)) { Write-Output "FAIL: exe not found at $exe"; exit 1 }

$script:failures = @()
function Fail([string]$case, [string]$msg) { $script:failures += ("[{0}] {1}" -f $case, $msg) }

function Compare-Node($expected, $actual, [string]$path, [string]$case) {
    if ($expected -is [System.Management.Automation.PSCustomObject]) {
        if ($actual -isnot [System.Management.Automation.PSCustomObject]) { Fail $case "$path : expected object, got '$actual'"; return }
        foreach ($p in $expected.PSObject.Properties) {
            if ($p.Name -eq 'reason') { continue }
            $ap = $actual.PSObject.Properties[$p.Name]
            if ($null -eq $ap) { Fail $case "$path.$($p.Name) : missing in actual output"; continue }
            Compare-Node $p.Value $ap.Value "$path.$($p.Name)" $case
        }
        return
    }
    if ($expected -is [Object[]]) {
        if ($actual -isnot [Object[]]) { Fail $case "$path : expected array, got '$actual'"; return }
        if ($expected.Count -ne $actual.Count) { Fail $case "$path : expected $($expected.Count) elements, got $($actual.Count)"; return }
        for ($i = 0; $i -lt $expected.Count; $i++) { Compare-Node $expected[$i] $actual[$i] "$path[$i]" $case }
        return
    }
    if ("$expected" -cne "$actual") { Fail $case "$path : expected '$expected', got '$actual'" }
}

function Invoke-Contract([string]$case, [string]$mode, [string]$dir, [string]$rules, [string]$out) {
    if (Test-Path $out) { Remove-Item $out -Force }
    $so = "$out.stdout"; $se = "$out.stderr"
    $args = @($mode, '--dir', "`"$dir`"", '--rules', "`"$rules`"", '--out', "`"$out`"")
    $p = Start-Process -FilePath $exe -ArgumentList $args -NoNewWindow -Wait -PassThru -RedirectStandardOutput $so -RedirectStandardError $se
    return @{ Exit = $p.ExitCode; StdOut = $so; StdErr = $se; Out = $out }
}

foreach ($caseDir in (Get-ChildItem $root -Directory | Sort-Object Name)) {
    $case  = $caseDir.Name
    $dir   = Join-Path $caseDir.FullName 'files'
    $rules = Join-Path $caseDir.FullName 'rules.json'
    $before = Get-ChildItem $dir -File | ForEach-Object { $_.Name } | Sort-Object

    foreach ($mode in @('--plan', '--explain')) {
        $label = if ($mode -eq '--plan') { 'plan' } else { 'trace' }
        $out = Join-Path $caseDir.FullName "actual-$label.json"
        $r = Invoke-Contract $case $mode $dir $rules $out

        if ($r.Exit -ne 0) { Fail $case "$mode exit code $($r.Exit); stderr: $((Get-Content $r.StdErr -Raw))"; continue }
        if (-not (Test-Path $out)) { Fail $case "$mode did not write $out"; continue }

        $bytes = [System.IO.File]::ReadAllBytes($out)
        if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { Fail $case "$mode output has a UTF-8 BOM" }

        $soText = if (Test-Path $r.StdOut) { [System.IO.File]::ReadAllText($r.StdOut) } else { '' }
        $lines = @($soText -split "`r?`n" | Where-Object { $_ -ne '' })
        if ($lines.Count -ne 1) { Fail $case "$mode printed $($lines.Count) stdout line(s), expected exactly 1. Content: '$soText'" }

        $after = Get-ChildItem $dir -File | ForEach-Object { $_.Name } | Sort-Object
        if (($before -join '|') -cne ($after -join '|')) { Fail $case "$mode MODIFIED THE FOLDER: '$($before -join '|')' -> '$($after -join '|')'" }

        $expectFile = Join-Path $caseDir.FullName "expect-$label.json"
        if (Test-Path $expectFile) {
            $exp = [System.IO.File]::ReadAllText($expectFile) | ConvertFrom-Json
            $act = [System.IO.File]::ReadAllText($out) | ConvertFrom-Json
            Compare-Node $exp $act $label $case
        }
    }
}

Write-Output '======================================================'
if ($script:failures.Count -eq 0) {
    Write-Output "ACCEPTANCE PASS - all $((Get-ChildItem $root -Directory).Count) cases, both contracts."
} else {
    Write-Output "ACCEPTANCE FAIL - $($script:failures.Count) problem(s):"
    $script:failures | ForEach-Object { Write-Output "  $_" }
}

