                    }

                    var op = opEl.GetString();
                    if (op is null)
                    {
                        continue;
                    }

                    var step = new RuleStep(op);
                    foreach (var prop in stepEl.EnumerateObject())
                    {
                        if (string.Equals(prop.Name, "op", StringComparison.Ordinal))
                        {
                            continue;
                        }

                        switch (prop.Value.ValueKind)
                        {
                            case JsonValueKind.String:
                                step.Params.Set(prop.Name, prop.Value.GetString() ?? "");
                                break;
                            case JsonValueKind.True:
                                step.Params.Set(prop.Name, true);
                                break;
                            case JsonValueKind.False:
                                step.Params.Set(prop.Name, false);
                                break;
                            case JsonValueKind.Number:
                                step.Params.Set(prop.Name, NumberToInt(prop.Value));
                                break;
                            default:
                                // null, array, object -> skip
                                break;
                        }
                    }

                    rules.Steps.Add(step);
                }
            }

            return rules;
        }
    }

    private static int NumberToInt(JsonElement element)
    {
        if (element.TryGetDouble(out var d))
        {
            var truncated = Math.Truncate(d);
            if (truncated >= int.MaxValue)
            {
                return int.MaxValue;
            }

            if (truncated <= int.MinValue)
            {
                return int.MinValue;
            }

            return (int)truncated;
        }

        return 0;
    }

    public static RuleSet LoadFile(string path)
    {
        var text = File.ReadAllText(path);
        return FromJson(text);
    }

    public string ToJson()
    {
        var doc = new RuleSetDocument
        {
            ApplyTo = ApplyTo == ApplyToMode.Name ? "name" : "nameAndExtension",
            Sort = Sort switch
            {
                SortMode.Created => "created",
                SortMode.Modified => "modified",
                _ => "name"
            },
            Steps = new List<Dictionary<string, object?>>()
        };

        foreach (var step in Steps)
        {
            var obj = new Dictionary<string, object?>(StringComparer.Ordinal) { ["op"] = step.Op };
            foreach (var kvp in step.Params.Raw)
            {
                obj[kvp.Key] = kvp.Value;
            }

            doc.Steps.Add(obj);
        }

        return JsonSerializer.Serialize(doc, JsonIo.DocumentOptions);
    }

    private sealed class RuleSetDocument
    {
        [JsonPropertyName("applyTo")]
        public string ApplyTo { get; set; } = "name";

        [JsonPropertyName("sort")]
        public string Sort { get; set; } = "name";

        [JsonPropertyName("steps")]
        public List<Dictionary<string, object?>> Steps { get; set; } = new();
    }
}
