namespace BatchRenameStudio.Core;

public sealed class ParamBag
{
    private readonly List<string> _order = new();
    private readonly Dictionary<string, object?> _values = new(StringComparer.Ordinal);

    public string GetString(string key, string fallback = "")
    {
        if (_values.TryGetValue(key, out var value) && value is string s)
        {
            return s;
        }

        return fallback;
    }

    public int GetInt(string key, int fallback = 0)
    {
        if (_values.TryGetValue(key, out var value) && value is int i)
        {
            return i;
        }

        return fallback;
    }

    public bool GetBool(string key, bool fallback = false)
    {
        if (_values.TryGetValue(key, out var value) && value is bool b)
        {
            return b;
        }

        return fallback;
    }

    public void Set(string key, string value)
    {
        SetInternal(key, value);
    }

    public void Set(string key, int value)
    {
        SetInternal(key, value);
    }

    public void Set(string key, bool value)
    {
        SetInternal(key, value);
    }

    private void SetInternal(string key, object? value)
    {
        if (!_values.ContainsKey(key))
        {
            _order.Add(key);
        }

        _values[key] = value;
    }

    public bool Has(string key)
    {
        return _values.ContainsKey(key);
    }

    public void Remove(string key)
    {
        if (_values.Remove(key))
        {
            _order.Remove(key);
        }
    }

    public IReadOnlyDictionary<string, object?> Raw
    {
        get
        {
            var ordered = new Dictionary<string, object?>(_order.Count, StringComparer.Ordinal);
            foreach (var key in _order)
            {
                ordered[key] = _values[key];
            }

            return ordered;
        }
    }

    public ParamBag Clone()
    {
        var clone = new ParamBag();
        foreach (var key in _order)
        {
            clone._order.Add(key);
            clone._values[key] = _values[key];
        }

        return clone;
    }
}

