using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace BatchRenameStudio.Rename;

public sealed class UndoEntry
{
    public string Path { get; init; } = "";
    public string Folder { get; init; } = "";
    public DateTime TimestampUtc { get; init; }
    public List<RenamePair> Pairs { get; init; } = new();
}

public static class UndoJournal
{
    private static readonly JsonSerializerOptions WriteOptions = new()
    {
        WriteIndented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    public static string Directory { get; } = Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio",
        "undo");

    public static string Write(string folder, IReadOnlyList<RenamePair> applied)
    {
        System.IO.Directory.CreateDirectory(Directory);

        var fileName = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff") + ".json";
        var path = Path.Combine(Directory, fileName);

        var doc = new JournalDocument
        {
            Folder = folder,
            TimestampUtc = DateTime.UtcNow,
            Pairs = applied.Select(p => new PairDocument { From = p.From, To = p.To }).ToList()
        };

        var bytes = JsonSerializer.SerializeToUtf8Bytes(doc, WriteOptions);
        File.WriteAllBytes(path, bytes);

        Prune();

        return path;
    }

    public static UndoEntry? ReadLatest()
    {
        if (!System.IO.Directory.Exists(Directory))
        {
            return null;
        }

