namespace BatchRenameStudio.Rename;

public sealed class RenamePair
{
    public string From { get; init; } = "";
    public string To { get; init; } = "";
}

public sealed class ApplyResult
{
    public int RenamedCount { get; set; }
    public List<string> Errors { get; } = new();
    public string? JournalPath { get; set; }
}

public static class RenameApplier
{
    // Two-phase so that swaps and cycles (a->b, b->a) work:
    //   phase 1: every source -> a unique temp name in the same folder
    //   phase 2: every temp -> its final target
    // If phase 2 hits an error, roll the already-moved files back to their ORIGINAL names
    // and report; never leave a file sitting under a temp name.
    public static ApplyResult Apply(string directory, IReadOnlyList<RenamePair> pairs, bool writeJournal = true)
    {
        var result = new ApplyResult();
        if (pairs.Count == 0)
        {
            return result;
        }

        var tempPaths = new string[pairs.Count];
        var movedToTemp = new List<int>();

        // Phase 1: source -> unique temp name.
        for (var i = 0; i < pairs.Count; i++)
        {
            var fromPath = Path.Combine(directory, pairs[i].From);
            var tempPath = BuildTempPath(directory, i, pairs[i].From);
            try
            {
                File.Move(fromPath, tempPath, false);
                tempPaths[i] = tempPath;
                movedToTemp.Add(i);
            }
            catch (Exception ex)
            {
                result.Errors.Add($"{pairs[i].From} -> {pairs[i].To}: {ex.Message}");
            }
        }

        // Phase 2: temp -> final target. Track successes for rollback on failure.
        var movedToFinal = new List<int>();
        var phase2Failed = false;

        foreach (var i in movedToTemp)
        {
            var toPath = Path.Combine(directory, pairs[i].To);
            try
            {
                File.Move(tempPaths[i], toPath, false);
                movedToFinal.Add(i);
                result.RenamedCount++;
            }
            catch (Exception ex)
            {
                result.Errors.Add($"{pairs[i].From} -> {pairs[i].To}: {ex.Message}");
                phase2Failed = true;
            }
        }

        var stillAtFinal = new HashSet<int>(movedToFinal);

        if (phase2Failed)
        {
            // Roll back everything that made it to the final target, back to its
            // original name, so nothing is left mid-flight. A rollback failure leaves
            // that one item at its final target, which is still tracked as renamed.
            foreach (var i in movedToFinal)
            {
                var toPath = Path.Combine(directory, pairs[i].To);
                var fromPath = Path.Combine(directory, pairs[i].From);
                try
                {
                    File.Move(toPath, fromPath, false);
                    result.RenamedCount--;
                    stillAtFinal.Remove(i);
                }
                catch (Exception ex)
                {
                    result.Errors.Add($"rollback {pairs[i].To} -> {pairs[i].From}: {ex.Message}");
                }
            }

            // Anything still sitting under a temp name (didn't reach phase 2 success) also
            // needs to go back to its original name.
            foreach (var i in movedToTemp)
            {
                if (movedToFinal.Contains(i))
                {
                    continue;
                }

                var fromPath = Path.Combine(directory, pairs[i].From);
                try
                {
                    if (File.Exists(tempPaths[i]))
                    {
                        File.Move(tempPaths[i], fromPath, false);
                    }
                }
                catch (Exception ex)
                {
                    result.Errors.Add($"rollback temp {pairs[i].From}: {ex.Message}");
                }
            }
        }

        // Journal exactly the pairs that are actually sitting at their final target
        // right now, whether that's the whole batch or a partial batch left over from
        // a rollback that itself hit an error.
        if (writeJournal && stillAtFinal.Count > 0)
        {
            var applied = new List<RenamePair>(stillAtFinal.Count);
            foreach (var i in movedToFinal)
            {
                if (stillAtFinal.Contains(i))
                {
                    applied.Add(pairs[i]);
                }
            }

            result.JournalPath = UndoJournal.Write(directory, applied);
        }

        return result;
    }

    private static string BuildTempPath(string directory, int index, string originalName)
    {
        var baseName = "__brs_" + index.ToString("D4") + "_" + originalName + ".tmp";
        var candidate = Path.Combine(directory, baseName);
        var suffix = 0;
        while (File.Exists(candidate))
        {
            suffix++;
            candidate = Path.Combine(directory, baseName + "_" + suffix);
        }

        return candidate;
    }
}

