# Second acceptance pass: determinism, error exit codes, degenerate inputs.
$ErrorActionPreference = 'Stop'
$exe  = Join-Path $PSScriptRoot 'exe-snapshot\BatchRenameStudio.exe'
$work = Join-Path $PSScriptRoot 'robust'
if (Test-Path $work) { Remove-Item $work -Recurse -Force }
New-Item -ItemType Directory -Path $work | Out-Null
$out = Join-Path $work 'out'; New-Item -ItemType Directory -Path $out | Out-Null

$fails = @()
function Run([string[]]$a, [string]$so) {
    $se = "$so.err"
    $p = Start-Process -FilePath $exe -ArgumentList $a -NoNewWindow -Wait -PassThru -RedirectStandardOutput $so -RedirectStandardError $se
    return $p.ExitCode
}

# --- R1 determinism: identical inputs -> byte-identical output, twice
$dir = Join-Path $PSScriptRoot 'accept\case05\files'
$rules = Join-Path $PSScriptRoot 'accept\case05\rules.json'
$o1 = Join-Path $out 'd1.json'; $o2 = Join-Path $out 'd2.json'
Run @('--plan','--dir',"`"$dir`"",'--rules',"`"$rules`"",'--out',"`"$o1`"") (Join-Path $out 'd1.txt') | Out-Null
Run @('--plan','--dir',"`"$dir`"",'--rules',"`"$rules`"",'--out',"`"$o2`"") (Join-Path $out 'd2.txt') | Out-Null
$h1 = (Get-FileHash $o1 -Algorithm SHA256).Hash; $h2 = (Get-FileHash $o2 -Algorithm SHA256).Hash
if ($h1 -ne $h2) { $fails += "R1 determinism: plan output differs between runs ($h1 vs $h2)" }
$t1 = Join-Path $out 't1.json'; $t2 = Join-Path $out 't2.json'
Run @('--explain','--dir',"`"$dir`"",'--rules',"`"$rules`"",'--out',"`"$t1`"") (Join-Path $out 't1.txt') | Out-Null
Run @('--explain','--dir',"`"$dir`"",'--rules',"`"$rules`"",'--out',"`"$t2`"") (Join-Path $out 't2.txt') | Out-Null
if ((Get-FileHash $t1).Hash -ne (Get-FileHash $t2).Hash) { $fails += 'R1 determinism: trace output differs between runs' }

# --- R2 empty folder (contains only a subdirectory)
$empty = Join-Path $work 'empty'; New-Item -ItemType Directory -Path (Join-Path $empty 'sub') -Force | Out-Null
[System.IO.File]::WriteAllText((Join-Path $empty 'sub\inner.txt'), 'x')
$oe = Join-Path $out 'empty.json'
$rc = Run @('--plan','--dir',"`"$empty`"",'--rules',"`"$rules`"",'--out',"`"$oe`"") (Join-Path $out 'empty.txt')
if ($rc -ne 0) { $fails += "R2 empty folder: exit $rc, expected 0" }
else {
    $j = Get-Content $oe -Raw | ConvertFrom-Json
    if ($j.summary.total -ne 0) { $fails += "R2 empty folder: total=$($j.summary.total), expected 0" }
    if ($j.items.Count -ne 0)   { $fails += "R2 empty folder: items=$($j.items.Count), expected 0" }
}

# --- R3 degenerate rules: unknown op, missing params, empty steps, no applyTo/sort
$degen = Join-Path $work 'degen'; New-Item -ItemType Directory -Path $degen | Out-Null
[System.IO.File]::WriteAllText((Join-Path $degen 'one.txt'), 'x')
$rd = Join-Path $work 'degen-rules.json'
[System.IO.File]::WriteAllText($rd, '{"steps":[{"op":"noSuchOp"},{"op":"pad"},{"op":"insert"},{"nope":1},"junk"]}')
$od = Join-Path $out 'degen.json'; $ot = Join-Path $out 'degen-trace.json'
$rc = Run @('--plan','--dir',"`"$degen`"",'--rules',"`"$rd`"",'--out',"`"$od`"") (Join-Path $out 'degen.txt')
if ($rc -ne 0) { $fails += "R3 degenerate rules: --plan exit $rc, expected 0" }
$rc = Run @('--explain','--dir',"`"$degen`"",'--rules',"`"$rd`"",'--out',"`"$ot`"") (Join-Path $out 'degen2.txt')
if ($rc -ne 0) { $fails += "R3 degenerate rules: --explain exit $rc, expected 0" }
else {
    $j = Get-Content $ot -Raw | ConvertFrom-Json
    if ($j.files[0].steps.Count -ne 3) { $fails += "R3: expected 3 trace steps (2 junk entries skipped), got $($j.files[0].steps.Count)" }
    if ($j.files[0].steps[0].op -ne 'noSuchOp') { $fails += "R3: unknown op id not preserved in trace" }
    if ($j.files[0].steps[0].before -cne $j.files[0].steps[0].after) { $fails += "R3: unknown op was not a no-op" }
}

# --- R4 error exit codes
$rc = Run @('--plan','--dir',"`"$degen`"",'--rules',"`"$rd`"") (Join-Path $out 'e1.txt')
if ($rc -ne 1) { $fails += "R4a missing --out: exit $rc, expected 1" }
$bad = Join-Path $work 'bad.json'; [System.IO.File]::WriteAllText($bad, '{')
$rc = Run @('--plan','--dir',"`"$degen`"",'--rules',"`"$bad`"",'--out',"`"$(Join-Path $out 'x.json')`"") (Join-Path $out 'e2.txt')
if ($rc -ne 2) { $fails += "R4b malformed rules: exit $rc, expected 2" }
$rc = Run @('--plan','--dir',"`"$(Join-Path $work 'nope')`"",'--rules',"`"$rd`"",'--out',"`"$(Join-Path $out 'y.json')`"") (Join-Path $out 'e3.txt')
if ($rc -ne 3) { $fails += "R4c missing dir: exit $rc, expected 3" }
$rc = Run @('--plan','--bogus','1','--dir',"`"$degen`"",'--rules',"`"$rd`"",'--out',"`"$(Join-Path $out 'z.json')`"") (Join-Path $out 'e4.txt')
if ($rc -ne 1) { $fails += "R4d unknown argument: exit $rc, expected 1" }
foreach ($f in @('e1.txt','e2.txt','e3.txt','e4.txt')) {
    $t = Get-Content (Join-Path $out $f) -Raw
    if ($t -and $t.Trim().Length -gt 0) { $fails += "R4 stdout polluted on error path ($f): '$t'" }
}

# --- R5 --out into a directory that does not exist yet
$deep = Join-Path $out 'a\b\c\plan.json'
$rc = Run @('--plan','--dir',"`"$degen`"",'--rules',"`"$rd`"",'--out',"`"$deep`"") (Join-Path $out 'r5.txt')
if ($rc -ne 0 -or -not (Test-Path $deep)) { $fails += "R5 nested --out path: exit $rc, exists=$(Test-Path $deep)" }

# --- R6 samples\rules\*.json all parse and run
$sdir = Join-Path $PSScriptRoot 'accept\case03\files'
foreach ($s in (Get-ChildItem 'D:\BenchRuns\XL-B-03\samples\rules' -Filter *.json)) {
    $so = Join-Path $out ("s-" + $s.BaseName + ".json")
    $rc = Run @('--plan','--dir',"`"$sdir`"",'--rules',"`"$($s.FullName)`"",'--out',"`"$so`"") (Join-Path $out ("s-" + $s.BaseName + ".txt"))
    if ($rc -ne 0) { $fails += "R6 sample $($s.Name): exit $rc" }
}

Write-Output '======================================================'
if ($fails.Count -eq 0) { Write-Output 'ROBUSTNESS PASS - determinism, empty folder, degenerate rules, exit codes, nested --out, samples.' }
else { Write-Output "ROBUSTNESS FAIL - $($fails.Count) problem(s):"; $fails | ForEach-Object { Write-Output "  $_" } }
